import { APP_INITIALIZER } from '@angular/core';
import { TestBed, fakeAsync, flushMicrotasks } from '@angular/core/testing';
import { take } from 'rxjs';
import { AppConfigService, MicroFrontConfigService, provideConfiguration, STATIC_CONF } from './app-config.service';

describe('provideConfiguration', () => {
  it('returns providers for APP_INITIALIZER and STATIC_CONF', () => {
    const providers = provideConfiguration();
    expect(providers.length).toBe(2);
    expect(providers.some((p: any) => p.provide === APP_INITIALIZER)).toBeTrue();
    expect(providers.some((p: any) => p.provide === STATIC_CONF)).toBeTrue();
  });

  it('APP_INITIALIZER factory invokes $$_loadConfig on the service', () => {
    const providers = provideConfiguration();
    const initProvider = providers.find((p: any) => p.provide === APP_INITIALIZER) as any;

    const loadSpy = jasmine.createSpy('$$_loadConfig').and.returnValue(Promise.resolve());
    const fakeService = { $$_loadConfig: loadSpy };

    const initializer = initProvider.useFactory(fakeService);
    initializer();

    expect(loadSpy).toHaveBeenCalled();
  });

  it('STATIC_CONF factory calls staticValue() on the service and returns the result', () => {
    const providers = provideConfiguration();
    const staticProvider = providers.find((p: any) => p.provide === STATIC_CONF) as any;

    const staticValueSpy = jasmine.createSpy('staticValue').and.returnValue({ conf: true });
    const fakeService = { staticValue: staticValueSpy };

    const result = staticProvider.useFactory(fakeService);

    expect(staticValueSpy).toHaveBeenCalled();
    expect(result).toEqual({ conf: true });
  });
});

describe('MicroFrontConfigService', () => {
  afterEach(() => {
    delete (window as any)._remove_mfa_config_url;
    TestBed.resetTestingModule();
  });

  it('registerRemote stores url and file under the given name', () => {
    TestBed.configureTestingModule({});
    const svc = TestBed.inject(MicroFrontConfigService);

    svc.registerRemote('myapp', 'https://cdn.example.com/', 'config.json');

    expect((window as any)._remove_mfa_config_url['myapp']).toEqual(['https://cdn.example.com/', 'config.json']);
  });

  it('registerRemote supports multiple names independently', () => {
    TestBed.configureTestingModule({});
    const svc = TestBed.inject(MicroFrontConfigService);

    svc.registerRemote('app1', 'https://a.com/', 'a.json');
    svc.registerRemote('app2', 'https://b.com/', 'b.json');

    expect((window as any)._remove_mfa_config_url['app1']).toEqual(['https://a.com/', 'a.json']);
    expect((window as any)._remove_mfa_config_url['app2']).toEqual(['https://b.com/', 'b.json']);
  });

  it('registerRemote appends to existing _remove_mfa_config_url without reinitializing', () => {
    (window as any)._remove_mfa_config_url = { existing: ['https://existing.com/', 'e.json'] };
    TestBed.configureTestingModule({});
    const svc = TestBed.inject(MicroFrontConfigService);

    svc.registerRemote('newapp', 'https://new.com/', 'new.json');

    expect((window as any)._remove_mfa_config_url['existing']).toEqual(['https://existing.com/', 'e.json']);
    expect((window as any)._remove_mfa_config_url['newapp']).toEqual(['https://new.com/', 'new.json']);
  });
});

describe('AppConfigService', () => {
  afterEach(() => TestBed.resetTestingModule());

  beforeEach(() => {
    spyOn(window, 'fetch').and.returnValue(Promise.resolve({ json: () => Promise.resolve({}) } as Response));
  });

  it('emits undefined for an unknown key before config loads', (done) => {
    TestBed.configureTestingModule({});
    const config = TestBed.inject(AppConfigService);

    config['unknownKey'].pipe(take(1)).subscribe((value: any) => {
      expect(value).toBeUndefined();
      done();
    });
  });

  it('emits the loaded value after mfeLoad resolves', fakeAsync(() => {
    (window.fetch as jasmine.Spy).and.returnValue(
      Promise.resolve({ json: () => Promise.resolve({ feature: 'enabled' }) } as Response),
    );
    TestBed.configureTestingModule({});
    const config = TestBed.inject(AppConfigService);

    const emitted: any[] = [];
    config['feature'].subscribe((v: any) => emitted.push(v));

    flushMicrotasks();

    expect(emitted).toContain('enabled');
  }));

  it('traverses dot-notation keys once config has loaded', fakeAsync(() => {
    (window.fetch as jasmine.Spy).and.returnValue(
      Promise.resolve({ json: () => Promise.resolve({ a: { b: 'deep-value' } }) } as Response),
    );
    TestBed.configureTestingModule({});
    const config = TestBed.inject(AppConfigService);

    const results: any[] = [];
    config['a.b'].subscribe((v: any) => results.push(v));

    flushMicrotasks();

    expect(results).toContain('deep-value');
  }));

  it('deepMerge handles nested objects and arrays from loaded config', fakeAsync(() => {
    (window.fetch as jasmine.Spy).and.returnValue(
      Promise.resolve({
        json: () => Promise.resolve({ nested: { x: 1 }, items: [1, 2, 3] }),
      } as Response),
    );
    TestBed.configureTestingModule({});
    const config = TestBed.inject(AppConfigService);

    const nestedValues: any[] = [];
    const itemsValues: any[] = [];
    config['nested'].subscribe((v: any) => nestedValues.push(v));
    config['items'].subscribe((v: any) => itemsValues.push(v));

    flushMicrotasks();

    expect(nestedValues).toContain(jasmine.objectContaining({ x: 1 }));
    expect(itemsValues).toContain([1, 2, 3]);
  }));

  it('deepMerge: source is a primitive → returns source (typeof source !== "object")', fakeAsync(() => {
    (window.fetch as jasmine.Spy).and.returnValue(
      Promise.resolve({ json: () => Promise.resolve('primitive') } as Response),
    );
    TestBed.configureTestingModule({});
    const config = TestBed.inject(AppConfigService);

    const results: any[] = [];
    // After deepMerge(env, 'primitive') returns 'primitive', values holds 'primitive'.
    // 'primitive'['length'] === 9
    config['length'].subscribe((v: any) => results.push(v));
    flushMicrotasks();

    expect(results).toContain(9);
  }));

  it('deepMerge: source is undefined → returns target (source !== undefined branch false)', fakeAsync(() => {
    (window.fetch as jasmine.Spy).and.returnValue(
      Promise.resolve({ json: () => Promise.resolve(undefined) } as Response),
    );
    TestBed.configureTestingModule({});
    const config = TestBed.inject(AppConfigService);

    const results: any[] = [];
    // deepMerge(env, undefined): typeof undefined !== 'object' → true
    // source !== undefined ? source : target → returns target (env = { name: 'lughauth' })
    config['name'].subscribe((v: any) => results.push(v));
    flushMicrotasks();

    expect(results).toContain('lughauth');
  }));

  it('calls mfeLoad only once even when value() is called multiple times', fakeAsync(() => {
    TestBed.configureTestingModule({});
    const config = TestBed.inject(AppConfigService);

    config['key1'].subscribe(() => {});
    config['key2'].subscribe(() => {});

    flushMicrotasks();

    expect(window.fetch as jasmine.Spy).toHaveBeenCalledTimes(1);
  }));
});

describe('AppConfigService — staticValue()', () => {
  afterEach(() => TestBed.resetTestingModule());

  it('throws when $$_loadConfig has not been called (shell = false)', () => {
    const providers = provideConfiguration();
    const staticProvider = providers.find((p: any) => p.provide === STATIC_CONF) as any;

    // Provide STATIC_CONF factory without APP_INITIALIZER → $$_loadConfig never runs → shell = false
    TestBed.configureTestingModule({
      providers: [{ provide: STATIC_CONF, deps: staticProvider.deps, useFactory: staticProvider.useFactory }],
    });

    expect(() => TestBed.inject(STATIC_CONF)).toThrowError('Static configuration is only available on the shell');
  });

  it('returns loaded config value once APP_INITIALIZER has run (shell = true)', fakeAsync(() => {
    spyOn(window, 'fetch').and.returnValue(
      Promise.resolve({ json: () => Promise.resolve({ shellKey: 'shellValue' }) } as Response),
    );

    TestBed.configureTestingModule({ providers: [...provideConfiguration()] });

    // Any inject triggers module init → APP_INITIALIZER runs → $$_loadConfig() called
    // shell = true is set synchronously (first line of $$_loadConfig, before any await)
    TestBed.inject(AppConfigService);
    // Flush microtasks to let the async fetch resolve and values.next() be called
    flushMicrotasks();

    const conf = TestBed.inject(STATIC_CONF);
    expect(conf).toEqual(jasmine.objectContaining({ shellKey: 'shellValue' }));
  }));
});

